  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Ofloxacin showed absolute oral bioavailability >95% in healthy volunteers after a 200 mg oral dose versus IV, directly supporting high F for a fluorinated heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Trovafloxacin had absolute oral bioavailability of 88% after a single 200 mg oral dose in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Levofloxacin is well absorbed from the gastrointestinal tract with bioavailability approaching 100% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Emtricitabine has an absolute oral bioavailability of 93% in humans, supporting high F for a small heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Nebivolol has absolute bioavailability of 96% in extensive metabolizers after oral administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C76"],
      "claim": "Didanosine oral bioavailability was 13% in children at 90 mg/m2, a sub-20% value; this is a formulation-sensitive nucleoside record and is outweighed by the high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of highly transferable experimental records—fluoroquinolones, emtricitabine, and nebivolol—shows absolute oral bioavailability well above 20% (88–100%). The only sub-20% record is didanosine in children, a formulation-dependent nucleoside case. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "The query's exact scaffold (triazole-pyridine-fluorophenyl-oxazolidinone) is not represented among the evidence molecules; extrapolation relies on assay-transfer scores.",
    "The only sub-20% record is didanosine in children, a formulation-sensitive nucleoside, leaving uncertainty about whether any similar absorption liability applies to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

